import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.Crpw6aS5.js";const m=JSON.parse('{"title":"EchoFlow Code：落地到真实开发流的 AI 编程工具","description":"","frontmatter":{"layout":"home","hero":{"name":"EchoFlow Code","text":"面向真实项目的本地 Coding Agent","tagline":"在终端、桌面端和 IM 里协同编码，内置清云 API（EchoFlowAPI），支持官方 Claude、Anthropic 兼容模型、多 Agent、记忆系统、Skills 与 Computer Use。","actions":[{"theme":"brand","text":"快速开始","link":"/guide/quick-start"},{"theme":"brand","text":"配置清云 API","link":"https://api.echoflow.cn/"},{"theme":"alt","text":"下载最新版","link":"https://github.com/LiuGuangHS/EchoFlow-ClaudeCode/releases/latest"},{"theme":"alt","text":"清云 AI 在线应用","link":"https://ai.echoflow.cn/"}]},"features":[{"icon":{"src":"/images/home/terminal-desktop.svg","alt":"CLI 与桌面端","width":32,"height":32,"wrap":false},"title":"CLI 与桌面端并行","details":"终端高频开发，桌面端负责多标签、项目选择和可视化设置。","link":"/desktop/"},{"icon":{"src":"/images/home/provider.svg","alt":"Provider","width":32,"height":32,"wrap":false},"title":"模型与 Provider 可控","details":"推荐清云 API，也支持 Anthropic / OpenAI 兼容网关和本地模型。","link":"/guide/third-party-models"},{"icon":{"src":"/images/home/agents.svg","alt":"多 Agent","width":32,"height":32,"wrap":false},"title":"多 Agent 协作","details":"并行探索、实现、审查与验证，用 Teams 和 Worktree 隔离复杂改动。","link":"/agent/"},{"icon":{"src":"/images/home/memory-skills.svg","alt":"记忆与 Skills","width":32,"height":32,"wrap":false},"title":"记忆与 Skills","details":"沉淀项目偏好、团队约束和可复用流程，减少重复解释。","link":"/memory/"},{"icon":{"src":"/images/home/mobile-im.svg","alt":"移动与 IM","width":32,"height":32,"wrap":false},"title":"移动与 IM 远程接入","details":"Android 扫码打开 H5，也可用 Telegram、飞书、微信、钉钉发起任务。","link":"/mobile/"},{"icon":{"src":"/images/home/computer-use.svg","alt":"Computer Use","width":32,"height":32,"wrap":false},"title":"Computer Use","details":"通过本地 Python Bridge 控制截图、鼠标、键盘和应用窗口。","link":"/features/computer-use"}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1783619669000}'),d={name:"index.md"};function i(l,e,h,n,s,c){return a(),o("div",null,[...e[0]||(e[0]=[r(`<h1 id="echoflow-code落地到真实开发流的-ai-编程工具" tabindex="-1">EchoFlow Code：落地到真实开发流的 AI 编程工具 <a class="header-anchor" href="#echoflow-code落地到真实开发流的-ai-编程工具" aria-label="Permalink to &quot;EchoFlow Code：落地到真实开发流的 AI 编程工具&quot;">​</a></h1><p>EchoFlow Code 是一个本地可运行的 Coding Agent 产品，覆盖 CLI、桌面端、本地服务、IM 适配器和文档化的质量门禁。它适合想把 AI 编程从“聊天窗口”推进到真实仓库、真实分支、真实验证流程里的个人开发者和工程团队。</p><h2 id="推荐使用清云-api" tabindex="-1">推荐使用清云 API <a class="header-anchor" href="#推荐使用清云-api" aria-label="Permalink to &quot;推荐使用清云 API&quot;">​</a></h2><p>新用户推荐优先使用 <strong>清云（EchoFlow）API</strong>：<a href="https://api.echoflow.cn" target="_blank" rel="noreferrer">api.echoflow.cn</a>。桌面端 Providers 页面提供清云 API 快捷接入卡片，可以注册账号、生成系统访问令牌、选择 main / haiku 模型并连接为默认 Provider。</p><p>清云 API 是 EchoFlow Code 的推荐模型入口：配置路径更短，和桌面端 Provider 流程贴合，也方便后续在官方 Claude、Anthropic 兼容协议、OpenAI 兼容网关和本地模型之间切换。已经有自有模型网关的团队，可以先用清云 API 跑通项目会话、多 Agent、记忆和 Computer Use，再按需要改成 Custom Provider。</p><h2 id="echoflow-生态入口" tabindex="-1">EchoFlow 生态入口 <a class="header-anchor" href="#echoflow-生态入口" aria-label="Permalink to &quot;EchoFlow 生态入口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>入口</th><th>地址</th><th>你可以做什么</th></tr></thead><tbody><tr><td>清云 API 主站</td><td><a href="https://api.echoflow.cn" target="_blank" rel="noreferrer">api.echoflow.cn</a></td><td>注册账号、获取系统访问令牌，为 EchoFlow Code 配置推荐 Provider。</td></tr><tr><td>清云 AI 在线应用站</td><td><a href="https://ai.echoflow.cn" target="_blank" rel="noreferrer">ai.echoflow.cn</a></td><td>直接体验清云 AI 在线应用，把轻量任务交给在线应用处理。</td></tr><tr><td>EchoFlow Code 文档</td><td><a href="https://code.echoflow.cn" target="_blank" rel="noreferrer">code.echoflow.cn</a></td><td>下载桌面端、阅读安装指南、配置模型和学习多 Agent 工作流。</td></tr></tbody></table><p>如果你只是想快速体验在线 AI 应用，先去 <a href="https://ai.echoflow.cn" target="_blank" rel="noreferrer">ai.echoflow.cn</a>。如果你要把 AI 落到本地代码仓库，下载 EchoFlow Code，并用 <a href="https://api.echoflow.cn" target="_blank" rel="noreferrer">api.echoflow.cn</a> 的清云 API 完成模型接入。</p><h2 id="适合谁" tabindex="-1">适合谁 <a class="header-anchor" href="#适合谁" aria-label="Permalink to &quot;适合谁&quot;">​</a></h2><ul><li>想继续使用终端工作流，但需要更完整桌面体验的开发者。</li><li>想把 Claude、OpenAI 兼容模型、EchoFlowAPI 或本地模型统一接入一个编码代理的团队。</li><li>需要多 Agent 并行处理探索、实现、审查、测试、发布任务的项目。</li><li>希望通过 Telegram、飞书、微信或钉钉远程发起任务、查看进度、继续会话的用户。</li><li>正在评估 Computer Use、桌面自动化、真实 UI 验收和本地权限控制的工程团队。</li></ul><h2 id="你可以用它做什么" tabindex="-1">你可以用它做什么 <a class="header-anchor" href="#你可以用它做什么" aria-label="Permalink to &quot;你可以用它做什么&quot;">​</a></h2><h3 id="在本地仓库里完成端到端编码任务" tabindex="-1">在本地仓库里完成端到端编码任务 <a class="header-anchor" href="#在本地仓库里完成端到端编码任务" aria-label="Permalink to &quot;在本地仓库里完成端到端编码任务&quot;">​</a></h3><p>EchoFlow Code 可以读取真实代码、编辑文件、运行测试、检查影响面，并按照仓库约束留下可交接的结果。终端 CLI 适合高频开发，桌面端适合多会话、多项目和可视化操作。</p><h3 id="用多-agent-拆解复杂问题" tabindex="-1">用多 Agent 拆解复杂问题 <a class="header-anchor" href="#用多-agent-拆解复杂问题" aria-label="Permalink to &quot;用多 Agent 拆解复杂问题&quot;">​</a></h3><p>多 Agent 系统适合把大任务拆成调研、实现、测试、审查等并行路径。配合 Worktree 隔离，可以降低多线探索互相污染的风险。</p><h3 id="让项目经验沉淀下来" tabindex="-1">让项目经验沉淀下来 <a class="header-anchor" href="#让项目经验沉淀下来" aria-label="Permalink to &quot;让项目经验沉淀下来&quot;">​</a></h3><p>记忆系统会把跨会话偏好、项目约定和历史决策变成可检索上下文。Skills 系统则把高频流程封装成可复用能力，让团队工作方式逐步稳定。</p><h3 id="从桌面移动端与-im-继续工作" tabindex="-1">从桌面、移动端与 IM 继续工作 <a class="header-anchor" href="#从桌面移动端与-im-继续工作" aria-label="Permalink to &quot;从桌面、移动端与 IM 继续工作&quot;">​</a></h3><p>桌面端提供会话、设置、Provider、IM 配置和 Computer Use 入口。Android 客户端可以扫码连接桌面端 H5 服务，在手机 WebView 中继续聊天、审批权限和上传文件；IM 适配器则让你可以在 Telegram、飞书、微信或钉钉里向本地 EchoFlow Code 发送任务。</p><h2 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre></div><p>桌面端用户可以直接前往 <a href="https://github.com/LiuGuangHS/EchoFlow-ClaudeCode/releases/latest" target="_blank" rel="noreferrer">GitHub Releases 下载最新版</a>，也可以先查看 <a href="/desktop/04-installation">安装与构建</a>。需要模型接入时，推荐先按 <a href="/desktop/01-quick-start">桌面端快速上手</a> 配置清云 API，再查看 <a href="/guide/third-party-models">第三方模型</a> 扩展其他 Provider。</p><h2 id="下载引导" tabindex="-1">下载引导 <a class="header-anchor" href="#下载引导" aria-label="Permalink to &quot;下载引导&quot;">​</a></h2><table tabindex="0"><thead><tr><th>你的设备</th><th>推荐下载</th><th>适合场景</th></tr></thead><tbody><tr><td>Windows x64</td><td><code>EchoFlow-Code-&lt;版本&gt;-win-x64.exe</code></td><td>日常桌面使用、多项目会话、Provider 可视化配置。</td></tr><tr><td>macOS Apple Silicon</td><td><code>EchoFlow-Code-&lt;版本&gt;-mac-arm64.dmg</code></td><td>M 系列 Mac 用户，适合桌面端和本地 Computer Use。</td></tr><tr><td>macOS Intel</td><td><code>EchoFlow-Code-&lt;版本&gt;-mac-x64.dmg</code></td><td>Intel Mac 用户，首次打开可能需要在系统安全设置中放行。</td></tr><tr><td>Linux x64</td><td><code>.AppImage</code> 或 <code>.deb</code></td><td>AppImage 适合免安装试用，deb 适合固定工作站环境。</td></tr><tr><td>Linux ARM64</td><td><code>linux-arm64.AppImage</code> 或 <code>linux-arm64.deb</code></td><td>ARM64 Linux 设备和开发机。</td></tr><tr><td>Android</td><td>移动端 APK / 本地构建</td><td>通过 H5 Token 扫码连接桌面端，适合可信局域网或自建 HTTPS 入口。</td></tr></tbody></table><p>不知道怎么选时，优先下载桌面端；已经习惯终端工作流的用户，可以直接用 CLI；安装包暂时不可用时，用 Web UI 模式在浏览器里连接本地服务。</p><h2 id="按用户类型推荐架构" tabindex="-1">按用户类型推荐架构 <a class="header-anchor" href="#按用户类型推荐架构" aria-label="Permalink to &quot;按用户类型推荐架构&quot;">​</a></h2><table tabindex="0"><thead><tr><th>用户类型</th><th>推荐架构</th><th>为什么这样选</th></tr></thead><tbody><tr><td>个人开发者</td><td>桌面端 + 清云 API / EchoFlowAPI Provider</td><td>安装后即可管理项目、会话和模型，配置成本最低。</td></tr><tr><td>终端重度用户</td><td>CLI + 本地仓库 + 项目级配置</td><td>保留 shell、git、测试命令和编辑器工作流，适合高频编码。</td></tr><tr><td>小团队协作</td><td>桌面端 + 多 Agent + 记忆系统 + Skills</td><td>把团队约束、常用流程和审查标准沉淀下来，减少重复解释。</td></tr><tr><td>多模型/私有模型用户</td><td>本地服务 + Anthropic/OpenAI 兼容 Provider + Ollama 或网关</td><td>统一模型入口，方便在云端模型、本地模型和代理网关之间切换。</td></tr><tr><td>移动远程使用</td><td>桌面端 + Android 客户端 / IM 适配器 + H5 Token + 本地服务</td><td>手机扫码进入 H5 或从 IM 发起任务，本地机器执行真实代码操作。</td></tr><tr><td>UI 自动化验证</td><td>桌面端 + Computer Use + 项目测试命令</td><td>让 Agent 能看见桌面、操作应用，并结合测试命令验证真实界面。</td></tr></tbody></table><p>架构选择可以从轻到重渐进：先用桌面端跑通 Provider 和项目会话，再按需要打开多 Agent、记忆、Skills、IM 或 Computer Use。这样不会一开始就把所有能力堆进工作流里。</p><h2 id="文档入口" tabindex="-1">文档入口 <a class="header-anchor" href="#文档入口" aria-label="Permalink to &quot;文档入口&quot;">​</a></h2><ul><li><a href="/guide/quick-start">快速开始</a>：安装、启动和基础使用。</li><li><a href="/desktop/">桌面端</a>：Electron 客户端、Provider、IM、Computer Use 和构建说明。</li><li><a href="/mobile/">移动端</a>：Android 客户端、扫码连接、H5 Token 和可信网络说明。</li><li><a href="/agent/">多 Agent 系统</a>：Agent 调用、Teams、并行任务和实现细节。</li><li><a href="/memory/">记忆系统</a>：记忆提取、检索、AutoDream 和本地存储。</li><li><a href="/skills/01-usage-guide">Skills 系统</a>：自定义能力、触发条件和执行约束。</li><li><a href="/im/">IM 接入</a>：Telegram、飞书、微信、钉钉等远程入口。</li><li><a href="/features/computer-use">Computer Use</a>：本地桌面控制能力与安全边界。</li></ul>`,30)])])}const u=t(d,[["render",i]]);export{m as __pageData,u as default};
